 
const Breadcrumb = () => {
 
  return (
    <section className="breadcrumb breadcrumb-one section-bg padding-y-60  position-relative z-index-1 overflow-hidden">
      <style>
        {`
          @media (max-width: 500px) {
            .breadcrumb-one.padding-y-60 {
              padding-top: 35px !important;
              padding-bottom: 25px !important;
            }
            .breadcrumb-one-content__title {
              font-size: 24px !important;
              line-height: 1.3 !important;
              margin-bottom: 12px !important;
            }
            .breadcrumb-one-content__desc {
              font-size: 13px !important;
              padding: 0 5px;
            }
          }
        `}
      </style>
      {/* section-bg  to get bg */}
      <img
        src="/assets/images/gradients/Bg2.webp"
        alt=""
        className="bg--gradient"
        loading="lazy"
      />
 
      <div className="container container-two">
        <div className="row justify-content-center">
          <div className="col-lg-7">
            <div className="breadcrumb-one-content">
              <h1 className="breadcrumb-one-content__title text-center mb-3 text-capitalize" style={{ fontSize: "35px" }}>
                Healthcare Services Made Simple
              </h1>
 
              <p className="breadcrumb-one-content__desc text-center text-black-three">
                Browse a wide range of medical services offered by nearby hospitals, clinics and labs.
                From consultations to diagnostics, find and book the right care — anytime, anywhere.
              </p>
 
             
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};
 
export default Breadcrumb;
 
 