import React, { useEffect, useState, useMemo } from "react";
import WindowedSelect from "react-windowed-select";

// Debounce helper
const useDebounce = (value, delay = 300) => {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const handler = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(handler);
  }, [value, delay]);

  return debounced;
};

// Helper function to convert string to title case
const toTitleCase = (str) => {
  return str
    .toLowerCase()
    .split(" ")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
};

const LocationSelect = ({ value, onChange, colClass = "col-sm-3" }) => {
  const [places, setPlaces] = useState([]);
  const [inputValue, setInputValue] = useState("");

  const debouncedInput = useDebounce(inputValue, 200); // 200ms debounce

  // Load places once
  useEffect(() => {
    const fetchPlaces = async () => {
      try {
        const res = await fetch("/Cities.json");
        if (!res.ok) throw new Error(`HTTP error! status: ${res.status}`);
        const data = await res.json();
        setPlaces(data); // keep raw array
      } catch (err) {
        console.error("Failed to load places:", err);
      }
    };
    fetchPlaces();
  }, []);

  // Filtered and memoized options
  const filteredOptions = useMemo(() => {
    if (!debouncedInput)
      return places.slice(0, 500).map((p) => ({
        value: p,
        label: toTitleCase(p),
      }));

    return places
      .filter((p) => p.toLowerCase().includes(debouncedInput.toLowerCase()))
      .slice(0, 500) // limit to top 500 matches
      .map((p) => ({
        value: p,
        label: toTitleCase(p),
      }));
  }, [places, debouncedInput]);

  // Convert current value to title case for display
  const displayValue = useMemo(() => {
    return value ? { value, label: toTitleCase(value) } : null;
  }, [value]);

  return (
    <div className={`${colClass} col-xs-6`}>
      <label className="form-label font-14">Search By District</label>
      <WindowedSelect
        options={filteredOptions}
        value={displayValue}
        onChange={(opt) => onChange(opt ? opt.value : "")}
        onInputChange={setInputValue} // track user input
        isClearable
        isSearchable
        placeholder="Search district..."
        menuPlacement="auto"
        windowThreshold={100} // virtualize after 100 items
        menuPortalTarget={document.body}
        maxMenuHeight={250}
        styles={{
          control: (base, state) => ({
            ...base,
            border: state.isFocused ? "1px solid #000424" : "1px solid #dcdcdc",
            borderRadius: "8px",
            minHeight: "48px",
            height: "48px",
            boxShadow: state.isFocused ? "0 0 0 2px rgba(0, 4, 36, 0.1)" : "none",
            "&:hover": { borderColor: state.isFocused ? "#000424" : "#c0c0c0" },
            backgroundColor: state.isDisabled ? "#f8f9fa" : "#fff",
            fontSize: "14px",
            transition: "all 0.2s ease",
            zIndex: 5,
          }),
          valueContainer: (base) => ({
            ...base,
            padding: "0 12px",
            height: "46px",
            display: "flex",
            alignItems: "center",
          }),
          placeholder: (base) => ({
            ...base,
            color: "#6c757d",
            fontSize: "14px",
            fontWeight: "400",
            margin: 0,
          }),
          singleValue: (base) => ({
            ...base,
            margin: 0,
            color: "#000",
          }),
          input: (base) => ({
            ...base,
            margin: 0,
            padding: 0,
          }),
          menuPortal: (base) => ({ 
            ...base, 
            zIndex: 9999 
          }),
          indicatorSeparator: () => ({ display: "none" }),
          dropdownIndicator: (base) => ({
            ...base,
            padding: "0 8px",
          }),
          option: (base, state) => ({
            ...base,
            backgroundColor: state.isSelected 
              ? "#000424" 
              : state.isFocused 
                ? "rgba(0, 4, 36, 0.05)" 
                : "transparent",
            color: state.isSelected ? "#fff" : "#333",
            cursor: state.isDisabled ? "not-allowed" : "pointer",
            padding: "10px 12px",
            fontSize: "14px",
            "&:active": {
              backgroundColor: "#000424",
              color: "#fff",
            },
          }),
        }}
      />
    </div>
  );
};

export default LocationSelect;
